textSample:
.avn-shell,
                .avn-shell * {
                    box-sizing: border-box;
                }

                .avn-shell {
                    container-type: inline-size;
                    position: relative;
                    z-index: 1000;
                    width: 100%;
                    min-width: 0;
                    overflow: visible;

                    font-family:
                        Inter,
                        ui-sans-serif,
                        system-ui,
                        -apple-system,
                        BlinkMacSystemFont,
                        "Segoe UI",
                        sans-serif;

                    color: rgb(17, 19, 24);
                }

                /* ========================================
                   MAIN NAV
                ======================================== */

                .avn-bar {
                    position: relative;
                    z-index: 2;

                    width: 100%;
                    min-height: 76px;

                    display: flex;
                    align-items: center;

                    gap: 20px;

                    padding: 0 48px;

                    background: rgba(255, 255, 255, 0.96);

                    border-bottom:
                        1px solid rgb(232, 234, 240);

                    backdrop-filter:
                        blur(18px);

                    -webkit-backdrop-filter:
                        blur(18px);
                }

                /* ========================================
                   LOGO
                ======================================== */

                .avn-logo,
                .avn-overlay-logo {
                    display: inline-flex;
                    align-items: center;

                    gap: 10px;

                    flex: 0 0 auto;

                    color: rgb(17, 19, 24);

                    text-decoration: none;

                    font-size: 13px;
                    line-height: 1;

                    font-weight: 780;
                    letter-spacing: 0.12em;

                    white-space: nowrap;
                }

                .avn-logo-dot {
                    width: 9px;
                    height: 9px;

                    flex: 0 0 auto;

                    border-radius: 999px;

                    background: rgb(94, 99, 232);

                    box-shadow:
                        0 0 0 5px
                        rgba(
                            94,
                            99,
                            232,
                            0.10
                        );
                }

                /* ========================================
                   DESKTOP NAV
                ======================================== */

                .avn-desktop {
                    flex: 1 1 auto;

                    min-width: 0;

                    align-self: stretch;

                    display: flex;

                    align-items: stretch;
                    justify-content: center;

                    gap: 2px;
                }

                .avn-group {
                    position: relative;

                    display: flex;
                    align-items: center;
                }

                .avn-toplink {
                    min-height: 76px;

                    display: inline-flex;

                    align-items: center;

                    gap: 5px;

                    padding: 0 8px;

                    color: rgb(101, 107, 120);

                    text-decoration: none;

                    font-size: 12.5px;
                    line-height: 1.2;

                    font-weight: 590;

                    white-space: nowrap;

                    transition:
                        color 160ms ease;
                }

                .avn-toplink:hover,
                .avn-toplink:focus-visible,
                .avn-group:hover > .avn-toplink,
                .avn-group:focus-within > .avn-toplink {
                    color: rgb(17, 19, 24);

                    outline: none;
                }

                .avn-chevron {
                    font-size: 10px;

                    opacity: 0.55;

                    transform:
                        translateY(-1px);

                    transition:
                        transform 160ms ease;
                }

                .avn-group:hover
                .avn-chevron,

                .avn-group:focus-within
                .avn-chevron {
                    transform:
                        translateY(-1px)
                        rotate(180deg);
                }

                /* ========================================
                   DESKTOP MEGA MENUS
                ======================================== */

                .avn-mega {
                    position: absolute;

                    top: calc(100% - 4px);
                    left: 50%;

                    width: 560px;

                    max-width:
                        calc(
                            100vw - 48px
                        );

                    padding: 12px;

                    border:
                        1px solid
                        rgb(232, 234, 240);

                    border-radius: 18px;

                    background:
                        rgba(
                            255,
                            255,
                            255,
                            0.99
                        );

                    box-shadow:
                        0 22px 60px
                        rgba(
                            18,
                            23,
                            38,
                            0.12
                        );

                    opacity: 0;

                    visibility: hidden;

                    pointer-events: none;

                    transform:
                        translate(
                            -50%,
                            -6px
                        );

                    transition:
                        opacity
                            150ms ease,
                        transform
                            170ms ease;
                }

                /*
                    Left-align early
                    menus so they
                    do not overflow.
                */

                .avn-group:nth-child(1)
                > .avn-mega,

                .avn-group:nth-child(2)
                > .avn-mega {
                    left: 0;

                    transform:
                        translate(
                            0,
                            -6px
                        );
                }

                .avn-group:nth-child(1):hover
                > .avn-mega,

                .avn-group:nth-child(1):focus-within
                > .avn-mega,

                .avn-group:nth-child(2):hover
                > .avn-mega,

                .avn-group:nth-child(2):focus-within
                > .avn-mega {
                    transform:
                        translate(
                            0,
                            0
                        );
                }

                /*
                    Resources opens
                    toward the left.
                */

                .avn-group:nth-child(5)
                > .avn-mega {
                    left: auto;
                    right: 0;

                    transform:
                        translate(
                            0,
                            -6px
                        );
                }

                .avn-group:nth-child(5):hover
                > .avn-mega,

                .avn-group:nth-child(5):focus-within
                > .avn-mega {
                    transform:
                        translate(
                            0,
                            0
                        );
                }

                .avn-group:hover
                > .avn-mega,

                .avn-group:focus-within
                > .avn-mega {
                    opacity: 1;

                    visibility: visible;

                    pointer-events: auto;

                    transform:
                        translate(
                            -50%,
                            0
                        );

                    transition-delay: 0s;
                }

                .avn-mega-grid {
                    display: grid;

                    grid-template-columns:
                        repeat(
                            2,
                            minmax(
                                0,
                                1fr
                            )
                        );

                    gap: 4px;
                }

                .avn-mega-item {
                    display: block;

                    min-width: 0;

                    padding:
                        13px 14px;

                    border-radius: 12px;

                    color: rgb(17, 19, 24);

                    text-decoration: none;

                    transition:
                        background
                            150ms ease,
                        transform
                            150ms ease;
                }

                .avn-mega-item:hover,
                .avn-mega-item:focus-visible {
                    background:
                        #F5F6FF;

                    transform:
                        translateY(-1px);

                    outline: none;
                }

                .avn-mega-title {
                    display: block;

                    margin-bottom: 4px;

                    font-size: 13px;
                    line-height: 1.25;

                    font-weight: 690;
                }

                .avn-mega-desc {
                    display: block;

                    color: rgb(101, 107, 120);

                    font-size: 11.5px;
                    line-height: 1.45;
                }

                /* ========================================
                   PRIMARY CTA
                ======================================== */

                .avn-cta {
                    min-height: 42px;

                    flex: 0 0 auto;

                    display: inline-flex;

                    align-items: center;
                    justify-content: center;

                    gap: 8px;

                    padding: 0 15px;

                    border-radius: 12px;

                    background: rgb(94, 99, 232);

                    border:
                        1px solid
                        transparent;

                    color: #FFFFFF;

                    text-decoration: none;

                    font-size: 12.5px;
                    line-height: 1;

                    font-weight: 670;

                    white-space: nowrap;

                    box-shadow:
                        0 8px 22px
                        rgba(
                            58,
                            64,
                            180,
                            0.18
                        );

                    transition:
                        transform
                            160ms ease,
                        box-shadow
                            160ms ease,
                        filter
                            160ms ease;
                }

                .avn-cta:hover,
                .avn-cta:focus-visible {
                    transform:
                        translateY(-1px);

                    filter:
                        brightness(0.97);

                    box-shadow:
                        0 10px 28px
                        rgba(
                            58,
                            64,
                            180,
                            0.23
                        );

                    outline: none;
                }

                /* ========================================
                   MOBILE BUTTONS
                ======================================== */

                .avn-menu-btn,
                .avn-overlay-close {
                    display: none;

                    width: 42px;
                    height: 42px;

                    flex: 0 0 auto;

                    padding: 0;

                    border:
                        1px solid
                        rgb(232, 234, 240);

                    border-radius: 12px;

                    background: #FFFFFF;

                    align-items: center;
                    justify-content: center;

                    cursor: pointer;
                }

                .avn-menu-btn:focus-visible,
                .avn-overlay-close:focus-visible {
                    outline:
                        2px solid
                        rgb(94, 99, 232);

                    outline-offset: 2px;
                }

                .avn-menu-icon {
                    width: 18px;
                    height: 14px;

                    position: relative;

                    display: block;
                }

                .avn-menu-icon span {
                    position: absolute;

                    left: 0;

                    width: 18px;
                    height: 1.5px;

                    border-radius: 99px;

                    background: rgb(17, 19, 24);
                }

                .avn-menu-icon
                span:nth-child(1) {
                    top: 1px;
                }

                .avn-menu-icon
                span:nth-child(2) {
                    top: 6px;
                }

                .avn-menu-icon
                span:nth-child(3) {
                    top: 11px;
                }

                /*
                    Hidden until
                    responsive breakpoint.
                */

                .avn-mobile-overlay {
                    display: none;
                }

                /* ========================================
                   COMPACT DESKTOP
                ======================================== */

                @container
                (max-width: 1120px) {

                    .avn-bar {
                        padding:
                            0 40px;

                        gap: 14px;
                    }

                    .avn-toplink {
                        padding:
                            0 6px;

                        font-size: 12px;
                    }

                    .avn-cta {
                        padding:
                            0 13px;

                        font-size: 12px;
                    }
                }

                /* ========================================
                   TABLET + MOBILE
                ======================================== */

                @container
                (max-width: 940px) {

                    .avn-bar {
                        min-height: 72px;

                        padding:
                            0 32px;
                    }

                    .avn-desktop,
                    .avn-cta {
                        display: none;
                    }

                    .avn-logo {
                        margin-right: auto;
                    }

                    .avn-menu-btn {
                        display: inline-flex;
                    }

                    /*
                        Full-screen fixed
                        overlay.
                    */

                    .avn-mobile-overlay {
                        position: fixed;

                        inset: 0;

                        z-index: 2147483000;

                        display: block;

                        width: 100vw;

                        height: 100vh;
                        height: 100dvh;

                        overflow-x: hidden;
                        overflow-y: auto;

                        overscroll-behavior:
                            contain;

                        background:
                            rgba(
                                255,
                                255,
                                255,
                                0.995
                            );

                        color: rgb(17, 19, 24);

                        opacity:
                            0;

                        visibility:
                            hidden;

                        pointer-events:
                            none;

                        transform:
                            translateY(-10px);

                        transition:
                            opacity
                                160ms ease,
                            transform
                                180ms ease,
                            visibility
                                0s linear
                                180ms;
                    }

                    .avn-mobile-frame {
                        width: 100%;

                        min-height: 100%;

                        display: flex;

                        flex-direction:
                            column;
                    }

                    /*
                        Overlay header
                    */

                    .avn-mobile-top {
                        position: sticky;

                        top: 0;

                        z-index: 2;

                        width: 100%;

                        min-height: 72px;

                        display: flex;

                        align-items: center;

                        gap: 16px;

                        padding:
                            0 32px;

                        background:
                            rgba(
                                255,
                                255,
                                255,
                                0.97
                            );

                        border-bottom:
                            1px solid
                            rgb(232, 234, 240);

                        backdrop-filter:
                            blur(18px);

                        -webkit-backdrop-filter:
                            blur(18px);
                    }

                    .avn-overlay-logo {
                        margin-right: auto;
                    }

                    .avn-overlay-close {
                        display: inline-flex;

                        font-size: 26px;

                        line-height: 1;

                        font-weight: 300;
                    }

                    /*
                        Menu content
                    */

                    .avn-mobile-content {
                        width:
                            min(
                                760px,
                                100%
                            );

                        margin:
                            0 auto;

                        padding:
                            24px
                            32px
                            34px;
                    }

                    .avn-mobile-group {
                        padding:
                            15px
                            0
                            17px;

                        border-bottom:
                            1px solid
                            rgb(232, 234, 240);
                    }

                    .avn-mobile-parent {
                        display:
                            inline-flex;

                        align-items:
                            center;

                        min-height:
                            34px;

                        color:
                            rgb(17, 19, 24);

                        text-decoration:
                            none;

                        font-size:
                            17px;

                        line-height:
                            1.2;

                        font-weight:
                            740;
                    }

                    .avn-mobile-children {
                        display: grid;

                        grid-template-columns:
                            repeat(
                                2,
                                minmax(
                                    0,
                                    1fr
                                )
                            );

                        gap:
                            4px
                            20px;

                        padding-top:
                            8px;
                    }

                    .avn-mobile-child {
                        min-width: 0;

                        padding:
                            9px 0;

                        color:
                            rgb(101, 107, 120);

                        text-decoration:
                            none;

                        font-size:
                            13px;

                        line-height:
                            1.35;

                        font-weight:
                            570;
                    }

                    .avn-mobile-child:hover,
                    .avn-mobile-child:focus-visible,
                    .avn-mobile-parent:hover,
                    .avn-mobile-parent:focus-visible {
                        color:
                            rgb(94, 99, 232);

                        outline: none;
                    }

                    /*
                        Mobile CTA
                    */

                    .avn-mobile-actions {
                        display: grid;

                        grid-template-columns:
                            1fr 1fr;

                        gap: 10px;

                        padding-top:
                            22px;
                    }

                    .avn-mobile-ghost,
                    .avn-mobile-primary {
                        min-height:
                            48px;

                        display:
                            inline-flex;

                        align-items:
                            center;

                        justify-content:
                            center;

                        padding:
                            0 16px;

                        border-radius:
                            12px;

                        text-decoration:
                            none;

                        font-size:
                            13px;

                        line-height:
                            1.2;

                        font-weight:
                            680;

                        text-align:
                            center;
                    }

                    .avn-mobile-ghost {
                        color:
                            rgb(17, 19, 24);

                        border:
                            1px solid
                            rgb(232, 234, 240);

                        background:
                            #FFFFFF;
                    }

                    .avn-mobile-primary {
                        color:
                            #FFFFFF;

                        background:
                            rgb(94, 99, 232);
                    }
                }

                /* ========================================
                   PHONE
                ======================================== */

                @container
                (max-width: 520px) {

                    .avn-bar {
                        min-height:
                            68px;

                        padding:
                            0 24px;
                    }

                    .avn-mobile-top {
                        min-height:
                            68px;

                        padding:
                            0 24px;
                    }

                    .avn-mobile-content {
                        padding:
                            18px
                            24px
                            28px;
                    }

                    .avn-mobile-group {
                        padding:
                            13px
                            0
                            15px;
                    }

                    .avn-mobile-parent {
                        font-size:
                            16px;
                    }

                    .avn-mobile-children {
                        grid-template-columns:
                            1fr;

                        gap: 0;
                    }

                    .avn-mobile-child {
                        padding:
                            7px 0;

                        font-size:
                            13px;
                    }

                    .avn-mobile-actions {
                        grid-template-columns:
                            1fr;
                    }
                }

                /* ========================================
                   ACCESSIBILITY
                ======================================== */

                @media
                (prefers-reduced-motion: reduce) {

                    .avn-mega,
                    .avn-mega-item,
                    .avn-cta,
                    .avn-mobile-overlay {
                        transition:
                            none !important;
                    }
                }

.avh-root {
                    position: relative;
                    isolation: isolate;
                    z-index: 0;
                }

                .avh-root,
                .avh-root * {
                    box-sizing: border-box;
                }

                .avh-root a {
                    -webkit-tap-highlight-color: transparent;
                }

                .avh-wrap {
                    position: relative;
                    z-index: 2;

                    width: 100%;
                    max-width: 1200px;
                    margin: 0 auto;

                    padding:
                        104px
                        48px
                        112px;

                    display: grid;

                    grid-template-columns:
                        minmax(0, 1fr)
                        minmax(420px, .92fr);

                    align-items: center;

                    gap: 72px;
                }

                .avh-content,
                .avh-visual-wrap,
                .avh-panel,
                .avh-node > div {
                    min-width: 0;
                }

                .avh-content {
                    max-width: 640px;
                }

                .avh-eyebrow {
                    display: inline-flex;

                    align-items: center;

                    gap: 9px;

                    margin-bottom: 26px;

                    color: var(--avh-text);

                    font-family:
                        "IBM Plex Mono",
                        ui-monospace,
                        SFMono-Regular,
                        Menlo,
                        Consolas,
                        monospace;

                    font-size: 12px;

                    line-height: 1.4;

                    letter-spacing: .08em;

                    text-transform: uppercase;

                    font-weight: 500;
                }

                .avh-dot {
                    width: 8px;
                    height: 8px;

                    flex: 0 0 auto;

                    border-radius: 999px;

                    background:
                        var(--avh-accent);

                    box-shadow:
                        0 0 0 5px
                        rgba(82,103,232,.10);

                    box-shadow:
                        0 0 0 5px
                        color-mix(
                            in srgb,
                            var(--avh-accent) 12%,
                            transparent
                        );
                }

                .avh-title {
                    margin: 0;

                    max-width: 690px;

                    color:
                        var(--avh-text);

                    font-size: 72px;

                    line-height: 1;

                    letter-spacing: -.052em;

                    font-weight: 600;

                    text-wrap: balance;

                    overflow-wrap: anywhere;
                }

                .avh-highlight {
                    color:
                        var(--avh-accent-text);
                }

                .avh-description {
                    max-width: 580px;

                    margin:
                        30px
                        0
                        0;

                    color:
                        var(--avh-muted);

                    font-size: 21px;

                    line-height: 1.58;

                    letter-spacing: -.015em;

                    overflow-wrap: anywhere;
                }

                .avh-actions {
                    display: flex;

                    align-items: center;

                    flex-wrap: wrap;

                    gap: 12px;

                    margin-top: 38px;
                }

                .avh-btn {
                    min-height: 48px;

                    padding:
                        0
                        22px;

                    border-radius: 12px;

                    display: inline-flex;

                    align-items: center;

                    justify-content: center;

                    gap: 9px;

                    text-decoration: none;

                    font-size: 14px;

                    line-height: 1.4;

                    font-weight: 600;

                    cursor: pointer;

                    user-select: none;

                    transition:
                        transform .2s ease,
                        box-shadow .2s ease,
                        background-color .2s ease,
                        border-color .2s ease;
                }

                .avh-btn:focus-visible {
                    outline:
                        3px solid
                        rgba(82,103,232,.25);

                    outline:
                        3px solid
                        color-mix(
                            in srgb,
                            var(--avh-accent) 28%,
                            transparent
                        );

                    outline-offset: 3px;
                }

                .avh-btn-primary {
                    background:
                        var(--avh-accent);

                    color: #FFFFFF;

                    box-shadow:
                        0 8px 24px
                        rgba(82,103,232,.18);

                    box-shadow:
                        0 8px 24px
                        color-mix(
                            in srgb,
                            var(--avh-accent) 22%,
                            transparent
                        );
                }

                .avh-btn-primary:hover {
                    transform:
                        translateY(-2px);

                    box-shadow:
                        0 12px 30px
                        rgba(82,103,232,.23);

                    box-shadow:
                        0 12px 30px
                        color-mix(
                            in srgb,
                            var(--avh-accent) 28%,
                            transparent
                        );
                }

                .avh-btn-secondary {
                    color:
                        var(--avh-text);

                    border:
                        1px solid
                        rgba(17,19,24,.12);

                    background:
                        rgba(255,255,255,.72);
                }

                .avh-btn-secondary:hover {
                    transform:
                        translateY(-2px);

                    background:
                        #FFFFFF;

                    border-color:
                        rgba(17,19,24,.18);
                }

                .avh-arrow {
                    font-size: 17px;

                    line-height: 1;

                    transform:
                        translateY(-1px);
                }

                .avh-trust {
                    display: flex;

                    flex-wrap: wrap;

                    gap:
                        12px
                        20px;

                    margin-top: 42px;

                    color:
                        var(--avh-muted);

                    font-size: 13px;

                    line-height: 1.4;
                }

                .avh-trust-item {
                    display: flex;

                    align-items: center;

                    gap: 7px;
                }

                .avh-check {
                    color:
                        var(--avh-accent-text);

                    font-weight: 700;
                }

                .avh-visual-wrap {
                    position: relative;

                    width: 100%;

                    min-height: 520px;

                    display: flex;

                    align-items: center;

                    justify-content: center;
                }

                .avh-glow {
                    position: absolute;

                    width:
                        min(
                            400px,
                            88%
                        );

                    aspect-ratio: 1;

                    border-radius: 50%;

                    background:
                        radial-gradient(
                            circle,
                            rgba(82,103,232,.14)
                            0%,
                            transparent
                            68%
                        );

                    background:
                        radial-gradient(
                            circle,
                            color-mix(
                                in srgb,
                                var(--avh-accent) 17%,
                                transparent
                            )
                            0%,
                            transparent
                            68%
                        );

                    filter:
                        blur(5px);

                    pointer-events: none;
                }

                .avh-panel {
                    position: relative;

                    width:
                        min(
                            100%,
                            500px
                        );

                    padding: 18px;

                    border-radius: 24px;

                    background:
                        rgba(
                            255,
                            255,
                            255,
                            .90
                        );

                    border:
                        1px solid
                        rgba(
                            17,
                            19,
                            24,
                            .09
                        );

                    box-shadow:
                        0 34px 90px
                        rgba(20,28,52,.12),

                        0 4px 14px
                        rgba(20,28,52,.04);

                    -webkit-backdrop-filter:
                        blur(16px);

                    backdrop-filter:
                        blur(16px);

                    animation:
                        avhPanelEnter
                        .82s
                        .08s
                        cubic-bezier(.2,.8,.2,1)
                        both;
                }

                .avh-panel-top {
                    display: flex;

                    align-items: center;

                    justify-content:
                        space-between;

                    gap: 16px;

                    padding:
                        2px
                        2px
                        16px;
                }

                .avh-panel-title {
                    color:
                        var(--avh-text);

                    font-size: 13px;

                    line-height: 1.35;

                    font-weight: 600;
                }

                .avh-live {
                    display:
                        inline-flex;

                    align-items: center;

                    gap: 7px;

                    flex:
                        0 0 auto;

                    padding:
                        7px
                        10px;

                    border-radius:
                        999px;

                    background:
                        #F2FAF5;

                    color:
                        #287A4B;

                    font-size:
                        11px;

                    line-height:
                        1;

                    font-weight:
                        600;
                }

