                    font-size: 10px;
                    font-weight: 700;
                    line-height: 1;
                    letter-spacing: 0.07em;
                    text-transform: uppercase;
                    background: rgba(102, 92, 255, 0.07);
                    border: 1px solid rgba(102, 92, 255, 0.12);
                }

                .avroi-liveDot {
                    width: 6px;
                    height: 6px;
                    border-radius: 50%;
                    background: var(--avroi-accent);
                    box-shadow:
                        0 0 0 4px rgba(102, 92, 255, 0.08);
                }

                .avroi-controls {
                    display: flex;
                    flex-direction: column;
                }

                .avroi-control {
                    padding: 22px 0 24px;
                    border-top: 1px solid rgba(18, 19, 24, 0.075);
                }

                .avroi-control:last-child {
                    padding-bottom: 10px;
                }

                .avroi-controlTop {
                    display: flex;
                    align-items: flex-start;
                    justify-content: space-between;
                    gap: 20px;
                    margin-bottom: 18px;
                }

                .avroi-controlLabel {
                    margin-bottom: 5px;
                    color: var(--avroi-text);
                    font-size: 13px;
                    font-weight: 620;
                    line-height: 1.3;
                    letter-spacing: -0.018em;
                }

                .avroi-controlHint {
                    max-width: 240px;
                    color: var(--avroi-muted);
                    font-size: 10px;
                    font-weight: 450;
                    line-height: 1.4;
                }

                .avroi-controlValue {
                    flex: 0 0 auto;
                    min-width: 58px;
                    padding: 8px 10px;
                    border-radius: 9px;
                    color: var(--avroi-text);
                    text-align: center;
                    font-size: 12px;
                    font-weight: 700;
                    line-height: 1;
                    font-variant-numeric: tabular-nums;
                    background: #F5F5F7;
                    border: 1px solid rgba(18, 19, 24, 0.07);
                }

                .avroi-rangeWrap {
                    width: 100%;
                }

                .avroi-range {
                    width: 100%;
                    height: 24px;
                    min-height: 24px;
                    margin: 0;
                    appearance: none;
                    -webkit-appearance: none;
                    background: transparent;
                    cursor: pointer;
                    outline: none;
                }

                .avroi-range::-webkit-slider-runnable-track {
                    width: 100%;
                    height: 4px;
                    border-radius: 999px;
                    background:
                        linear-gradient(
                            90deg,
                            var(--avroi-accent) 0%,
                            var(--avroi-accent) var(--avroi-progress),
                            #E7E7EC var(--avroi-progress),
                            #E7E7EC 100%
                        );
                }

                .avroi-range::-webkit-slider-thumb {
                    width: 18px;
                    height: 18px;
                    margin-top: -7px;
                    appearance: none;
                    -webkit-appearance: none;
                    border-radius: 50%;
                    border: 4px solid var(--avroi-surface);
                    background: var(--avroi-accent);
                    box-shadow:
                        0 0 0 1px rgba(102, 92, 255, 0.18),
                        0 4px 10px rgba(18, 19, 24, 0.14);
                    transition:
                        transform 160ms ease,
                        box-shadow 160ms ease;
                }

                .avroi-range:hover::-webkit-slider-thumb {
                    transform: scale(1.08);
                    box-shadow:
                        0 0 0 4px rgba(102, 92, 255, 0.08),
                        0 4px 12px rgba(18, 19, 24, 0.16);
                }

                .avroi-range:focus-visible::-webkit-slider-thumb {
                    box-shadow:
                        0 0 0 4px rgba(102, 92, 255, 0.18),
                        0 4px 12px rgba(18, 19, 24, 0.16);
                }

                .avroi-range::-moz-range-track {
                    width: 100%;
                    height: 4px;
                    border-radius: 999px;
                    background: #E7E7EC;
                }

                .avroi-range::-moz-range-progress {
                    height: 4px;
                    border-radius: 999px;
                    background: var(--avroi-accent);
                }

                .avroi-range::-moz-range-thumb {
                    width: 12px;
                    height: 12px;
                    border-radius: 50%;
                    border: 4px solid var(--avroi-surface);
                    background: var(--avroi-accent);
                    box-shadow:
                        0 0 0 1px rgba(102, 92, 255, 0.18);
                }

                .avroi-rangeLabels {
                    display: flex;
                    justify-content: space-between;
                    margin-top: 2px;
                    color: #5F6472;
                    font-size: 10px;
                    font-weight: 550;
                    line-height: 1;
                }

                .avroi-outputPanel {
                    position: relative;
                    isolation: isolate;
                    display: flex;
                    flex-direction: column;
                    padding: 32px;
                    overflow: hidden;
                    color: white;
                    background: var(--avroi-dark);
                }

                .avroi-outputPanel::before {
                    content: "";
                    position: absolute;
                    z-index: -2;
                    width: 520px;
                    height: 520px;
                    top: -320px;
                    right: -170px;
                    border-radius: 50%;
                    background:
                        radial-gradient(
                            circle,
                            rgba(102, 92, 255, 0.26) 0%,
                            rgba(102, 92, 255, 0.08) 38%,
                            transparent 70%
                        );
                    pointer-events: none;
                }

                .avroi-outputPanel::after {
                    content: "";
                    position: absolute;
                    z-index: -2;
                    inset: 0;
                    opacity: 0.22;
                    pointer-events: none;
                    background-image:
                        linear-gradient(
                            rgba(255, 255, 255, 0.022) 1px,
                            transparent 1px
                        ),
                        linear-gradient(
                            90deg,
                            rgba(255, 255, 255, 0.022) 1px,
                            transparent 1px
                        );
                    background-size: 28px 28px;
                    mask-image:
                        linear-gradient(
                            to bottom,
                            black,
                            transparent 80%
                        );
                }

                .avroi-outputTop {
                    display: flex;
                    align-items: flex-start;
                    justify-content: space-between;
                    gap: 22px;
                    margin-bottom: 26px;
                }

                .avroi-outputEyebrow {
                    display: flex;
                    align-items: center;
                    gap: 8px;
                    margin-bottom: 8px;
                    color: var(--avroi-accent-text-dark);
                    font-size: 10px;
                    font-weight: 700;
                    line-height: 1;
                    letter-spacing: 0.10em;
                    text-transform: uppercase;
                }

                .avroi-outputTitle {
                    margin: 0;
                    max-width: 330px;
                    color: rgba(255, 255, 255, 0.94);
                    font-size: 23px;
                    font-weight: 620;
                    line-height: 1.12;
                    letter-spacing: -0.038em;
                }

                .avroi-estimateTag {
                    flex: 0 0 auto;
                    padding: 8px 10px;
                    border-radius: 999px;
                    color: rgba(255, 255, 255, 0.68);
                    font-size: 10px;
                    font-weight: 700;
                    line-height: 1;
                    letter-spacing: 0.08em;
                    text-transform: uppercase;
                    background: rgba(255, 255, 255, 0.04);
                    border: 1px solid rgba(255, 255, 255, 0.07);
                }

                .avroi-primaryMetric {
                    position: relative;
                    padding: 28px;
                    margin-bottom: 14px;
                    overflow: hidden;
                    border-radius: 18px;
                    background:
                        linear-gradient(
                            140deg,
                            rgba(102, 92, 255, 0.18),
                            rgba(102, 92, 255, 0.055) 55%,
                            rgba(255, 255, 255, 0.035)
                        );
                    border: 1px solid rgba(130, 120, 255, 0.20);
                }

                .avroi-primaryMetric::before {
                    content: "";
                    position: absolute;
                    top: 0;
                    left: 20px;
                    right: 20px;
                    height: 1px;
                    background:
                        linear-gradient(
                            90deg,
                            transparent,
                            rgba(151, 143, 255, 0.90),
                            transparent
                        );
                }

                .avroi-primaryLabel {
                    margin-bottom: 11px;
                    color: rgba(255, 255, 255, 0.68);
                    font-size: 10px;
                    font-weight: 700;
                    line-height: 1;
                    letter-spacing: 0.10em;
                    text-transform: uppercase;
                }

                .avroi-primaryValue {
                    display: flex;
                    align-items: baseline;
                    gap: 8px;
                    color: white;
                    font-size: clamp(46px, 5vw, 66px);
                    font-weight: 650;
                    line-height: 0.96;
                    letter-spacing: -0.06em;
                    font-variant-numeric: tabular-nums;
                }

                .avroi-primarySuffix {
                    color: var(--avroi-accent-text-dark);
                    font-size: 16px;
                    font-weight: 620;
                    letter-spacing: -0.02em;
                }

                .avroi-primarySub {
                    margin-top: 13px;
                    max-width: 390px;
                    color: rgba(255, 255, 255, 0.68);
                    font-size: 10px;
                    line-height: 1.5;
                }

                .avroi-metricGrid {
                    display: grid;
                    grid-template-columns:
                        repeat(2, minmax(0, 1fr));
                    gap: 14px;
                    margin-bottom: 14px;
                }

                .avroi-metric {
                    min-width: 0;
                    min-height: 125px;
                    display: flex;
                    flex-direction: column;
                    justify-content: space-between;
                    padding: 18px;
                    border-radius: 15px;
                    background: rgba(255, 255, 255, 0.038);
                    border: 1px solid rgba(255, 255, 255, 0.06);
                }

                .avroi-metricHead {
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    gap: 14px;
                }

                .avroi-metricIcon {
                    width: 32px;
                    height: 32px;
                    flex: 0 0 32px;
                    display: grid;
                    place-items: center;
                    border-radius: 9px;
                    color: var(--avroi-accent-text-dark);
                    background: rgba(102, 92, 255, 0.13);
                    border: 1px solid rgba(130, 120, 255, 0.13);
                }

                .avroi-metricLabel {
                    color: rgba(255, 255, 255, 0.68);
                    font-size: 10px;
                    font-weight: 700;
                    line-height: 1.15;
                    letter-spacing: 0.09em;
                    text-align: right;
                    text-transform: uppercase;
                }

                .avroi-metricValue {
                    margin-top: 18px;
                    overflow: hidden;
                    color: rgba(255, 255, 255, 0.94);
                    font-size: 25px;
                    font-weight: 620;
                    line-height: 1;
                    letter-spacing: -0.04em;
                    font-variant-numeric: tabular-nums;
                    text-overflow: ellipsis;
                    white-space: nowrap;
                }

                .avroi-metricUnit {
                    margin-left: 4px;
                    color: rgba(255, 255, 255, 0.68);
                    font-size: 10px;
                    font-weight: 550;
                    letter-spacing: 0;
                }

                .avroi-opportunity {
                    margin-top: auto;
                    padding: 19px 20px 18px;
                    border-radius: 15px;
                    background: rgba(255, 255, 255, 0.038);
                    border: 1px solid rgba(255, 255, 255, 0.06);
                }

                .avroi-opportunityTop {
                    display: flex;
                    align-items: flex-start;
                    justify-content: space-between;
                    gap: 20px;
                    margin-bottom: 16px;
                }

                .avroi-opportunityLabel {
                    margin-bottom: 5px;
                    color: rgba(255, 255, 255, 0.68);
                    font-size: 10px;
                    font-weight: 700;
                    line-height: 1;
                    letter-spacing: 0.09em;
                    text-transform: uppercase;
                }

                .avroi-opportunityValue {
                    color: rgba(255, 255, 255, 0.92);
                    font-size: 14px;
                    font-weight: 620;
                    letter-spacing: -0.018em;
                }

                .avroi-opportunityStatus {
                    display: flex;
                    align-items: center;
                    gap: 7px;
                    color: var(--avroi-accent-text-dark);
                    font-size: 10px;
                    font-weight: 700;
                    letter-spacing: 0.075em;
                    text-transform: uppercase;
                    white-space: nowrap;
                }

                .avroi-opportunityDot {
                    width: 6px;
                    height: 6px;
                    border-radius: 50%;
                    background: #7770FF;
                    box-shadow:
                        0 0 0 4px rgba(102, 92, 255, 0.08);
                }

                .avroi-meter {
                    width: 100%;
                    height: 5px;
                    overflow: hidden;
                    border-radius: 999px;
                    background: rgba(255, 255, 255, 0.07);
                }

                .avroi-meterFill {
                    height: 100%;
                    border-radius: inherit;
                    background:
                        linear-gradient(
                            90deg,
                            #665CFF,
                            #9B95FF
                        );
                    transition: width 260ms ease;
                    box-shadow:
                        0 0 18px rgba(102, 92, 255, 0.28);
                }

                .avroi-opportunityCopy {
                    margin: 11px 0 0;
                    color: rgba(255, 255, 255, 0.68);
                    font-size: 10px;
                    line-height: 1.5;
                }

                .avroi-evidence {
                    display: grid;
                    grid-template-columns: repeat(3, minmax(0, 1fr));
                    gap: 10px;
                    margin-top: 24px;
                }

                .avroi-evidenceStep {
                    min-width: 0;
                    padding: 17px 18px;
                    border-radius: 14px;
                    border: 1px solid rgba(18, 19, 24, 0.08);
                    background: rgba(255, 255, 255, 0.72);
                }

                .avroi-evidenceKicker {
                    margin-bottom: 7px;
                    color: var(--avroi-accent-text);
                    font-size: 10px;
                    font-weight: 750;
                    line-height: 1;
                    letter-spacing: 0.10em;
                    text-transform: uppercase;
                }

                .avroi-evidenceTitle {
                    margin: 0;
                    color: var(--avroi-text);
                    font-size: 13px;
                    font-weight: 650;
                    line-height: 1.3;
                    letter-spacing: -0.018em;
                }

                .avroi-evidenceCopy {
                    margin: 6px 0 0;
                    color: var(--avroi-muted);
                    font-size: 10px;
                    line-height: 1.5;
                }

                .avroi-bottom {
                    display: grid;
                    grid-template-columns:
                        1.05fr
                        0.95fr;
                    margin-top: 24px;
                    overflow: hidden;
                    border-radius: 16px;
                    border: 1px solid rgba(18, 19, 24, 0.08);
                    background: var(--avroi-surface);
                }

                .avroi-bottomBlock {
                    min-height: 96px;
                    display: flex;
                    align-items: center;
                    gap: 15px;
                    padding: 20px 22px;
                }

                .avroi-bottomBlock:first-child {
                    border-right: 1px solid rgba(18, 19, 24, 0.07);
                }

                .avroi-bottomIcon {
                    width: 38px;
                    height: 38px;
                    flex: 0 0 38px;
                    display: grid;
                    place-items: center;
                    border-radius: 11px;
                    color: var(--avroi-accent-text);
                    background: rgba(102, 92, 255, 0.07);
                    border: 1px solid rgba(102, 92, 255, 0.10);
                }

                .avroi-bottomLabel {
                    margin-bottom: 5px;
                    color: var(--avroi-muted);
                    font-size: 10px;
                    font-weight: 700;
                    line-height: 1;
                    letter-spacing: 0.09em;
                    text-transform: uppercase;
                }

                .avroi-bottomValue {
                    color: var(--avroi-text);
                    font-size: 12px;
                    font-weight: 600;
                    line-height: 1.4;
                    letter-spacing: -0.015em;
                }

                .avroi-bottomAction {
                    justify-content: space-between;
                }

                .avroi-arrow {
                    width: 34px;
                    height: 34px;
                    flex: 0 0 34px;
                    display: grid;
                    place-items: center;
                    border-radius: 50%;
                    color: var(--avroi-text);
                    background: #F5F5F7;
                    border: 1px solid rgba(18, 19, 24, 0.07);
                }

                @media (max-width: 1199px) {
                    .avroi-wrap {
                        padding: 96px 36px 100px;
                    }

                    .avroi-wrap::before {
                        left: 36px;
                        right: 36px;
                    }

                    .avroi-header {
                        gap: 44px;
                        margin-bottom: 42px;
                    }

                    .avroi-heading {
                        font-size: clamp(40px, 5.3vw, 58px);
                    }

                    .avroi-calculator {
                        grid-template-columns:
                            minmax(310px, 0.9fr)
                            minmax(0, 1.1fr);
                    }

                    .avroi-inputPanel,
                    .avroi-outputPanel {
                        padding: 26px;
                    }

                    .avroi-primaryMetric {
                        padding: 23px;
                    }

                    .avroi-primaryValue {
                        font-size: 54px;
                    }
                }

                @media (max-width: 809px) {
                    .avroi-wrap {
                        padding: 76px 20px 80px;
                    }

                    .avroi-wrap::before {
                        left: 20px;
                        right: 20px;
                    }

                    .avroi-header {
                        grid-template-columns: 1fr;
                        gap: 24px;
                        margin-bottom: 34px;
                    }

                    .avroi-copy {
                        max-width: 600px;
                        justify-self: start;
                    }

                    .avroi-heading {
                        max-width: 650px;
                        font-size: clamp(36px, 10vw, 49px);
                        line-height: 1.01;
                        letter-spacing: -0.05em;
                    }

                    .avroi-description {
                        font-size: 14px;
                    }

                    .avroi-calculator {
                        grid-template-columns: 1fr;
                        border-radius: 19px;
                    }

                    .avroi-inputPanel,
                    .avroi-outputPanel {
                        padding: 24px 20px;
                    }

                    .avroi-inputPanel {
                        border-bottom: 1px solid rgba(255, 255, 255, 0.05);
                    }

                    .avroi-controlHint {
                        max-width: 220px;
                    }

                    .avroi-outputPanel {
                        min-height: 560px;
                    }

                    .avroi-primaryMetric {
                        padding: 22px;
                    }

                    .avroi-primaryValue {
                        font-size: clamp(48px, 14vw, 62px);
                    }

                    .avroi-evidence {
                        grid-template-columns: 1fr;
                        gap: 8px;
                    }

                    .avroi-bottom {
                        grid-template-columns: 1fr;
                        border-radius: 14px;
                    }

                    .avroi-bottomBlock {
                        min-height: 88px;
                    }

                    .avroi-bottomBlock:first-child {
                        border-right: 0;
                        border-bottom: 1px solid rgba(18, 19, 24, 0.07);
                    }
                }

                @media (max-width: 479px) {
                    .avroi-heading {
                        font-size: 38px;
                    }

                    .avroi-panelTop,
                    .avroi-outputTop {
                        flex-direction: column;
                        align-items: flex-start;
                    }

                    .avroi-controlTop {
                        gap: 12px;
                    }

                    .avroi-controlHint {
                        max-width: 185px;
                    }

                    .avroi-metricGrid {
                        grid-template-columns: 1fr;
                    }

                    .avroi-metric {
                        min-height: 112px;
                    }

                    .avroi-opportunityTop {
                        flex-direction: column;
                        gap: 10px;
                    }
                }

                @media (prefers-reduced-motion: reduce) {
                    .avroi-root *,
                    .avroi-root *::before,
                    .avroi-root *::after {
                        scroll-behavior: auto !important;
                        transition-duration: 0.001ms !important;
                        animation-duration: 0.001ms !important;
                        animation-iteration-count: 1 !important;
                    }
                }
